            new Quote { Id = "https://pl.wikiquote.org/wiki/Ignacy_Krasicki", Text = "Wiecznej, prawda, pamięci są pisarze godni, Lecz cóż sława po śmierci? gdy za życia głodni?", Author = "Ignacy Krasicki" },
