            new Quote { Id = "https://pl.wikiquote.org/wiki/Ignacy_Krasicki", Text = "Ktokolwiek mówi, iż się śmierci nie lęka, kłamie.", Author = "Ignacy Krasicki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ignacy_Krasicki", Text = "Milsza śmierć wolna, niż życie w kajdanach.", Author = "Ignacy Krasicki" },
