            new Quote { Id = "https://pl.wikiquote.org/wiki/Ignacy_Krasicki", Text = "Tego imię za życia wypisane jest w niebie, komu chlebem powszednim jest ofiara z siebie.", Author = "Ignacy Krasicki" },
